from ta_emss.utilities.SCFC_parser_lib.scfc_elements.Managed_Object_Label import ManagedObjectLabel
from ta_emss.utilities.SCFC_parser_lib.scfc_elements.Managed_Object_Attribute import ManagedObjectScalarAttribute, \
    ManagedObjectStructuralAttribute


class ManagedObject(object):
    def __init__(self, xml_managed_object, to_replace=None):
        self.xml = xml_managed_object
        self.label = ManagedObjectLabel(self.get_object_path(), to_replace)
        self.attributes = self.create_attibutes()
        self.operation = str(self.get_object_operation())

    def get_attribute_dict(self):
        return {attribute.get_name(): attribute.get_emss_value() for attribute in self.attributes}

    def get_yaml_object_dict(self):
        attr_dict = self.get_attribute_dict()
        if self.is_to_delete():
            attr_dict['DEL'] = 1
        return {self.label.get_yaml_name(): attr_dict}

    def get_emss_object_dict(self):
        return {self.label.get_emss_name(): self.get_attribute_dict()}

    def get_object_path(self):
        return self.xml.attributes['distName'].value

    def get_object_operation(self):
        return self.xml.attributes['operation'].value

    def get_attribute_nodes(self):
        return [node for node in self.xml.childNodes if self.is_attribute_node(node)]

    def is_to_delete(self):
        return str.lower(self.operation) == "delete"

    def is_attribute_node(self, node):
        return self.is_scalar_attribute(node) or self.is_structural_attribute(node)

    def create_attibutes(self):
        return [self.create_attibute(attribute_node) for attribute_node in self.get_attribute_nodes()]

    def is_scalar_attribute(self, node):
        return node.nodeName == 'p'

    def is_structural_attribute(self, node):
        return node.nodeName == 'list'

    def create_attibute(self, node):
        if self.is_scalar_attribute(node):
            return ManagedObjectScalarAttribute(node)
        elif self.is_structural_attribute(node):
            return ManagedObjectStructuralAttribute(node)
